mapper.delete:
delete from t_cruise_point_instance
        where device_mete_id = #{deviceMeteId, jdbcType=BIGINT}
        and cruise_type = #{cruiseType,jdbcType=VARCHAR}

mapper.select:
select
a.instance_id,
a.device_mete_id,
a.station_id,
a.station_name,
a.device_id,
a.custom_id,
a.data_format,
a.identify_type,
a.identify_son_type,
a.cruise_type,
a.cruise_id,
a.cruise_name,
a.cruise_content,
a.position_type,
a.unit,
a.if_sy,
a.sy_type,
a.if_videotape,
a.videotape_time,
a.text_desc,
a.sort,
b.device_name as deviceName,
b.custom_name as customName,
f.dict_note as cruiseTypeName
from t_cruise_point_instance a,t_std_device b,t_dict_business f
where 1 = 1 and a.device_id = b.device_id and a.custom_id= b.custom_id  and a.cruise_type = f.dict_code
 and a.instance_id = #{instanceId, jdbcType=BIGINT}
 and a.device_mete_id = #{deviceMeteId, jdbcType=BIGINT}
 and a.station_id = #{stationId, jdbcType=VARCHAR}
 and a.station_name = #{stationName, jdbcType=VARCHAR}
 and a.device_id = #{deviceId, jdbcType=BIGINT}
 and a.custom_id = #{customId, jdbcType=VARCHAR}
 and a.data_format = #{dataFormat, jdbcType=VARCHAR}
 and a.identify_type = #{identifyType, jdbcType=INTEGER}
 and a.identify_son_type = #{identifySonType, jdbcType=INTEGER}
 and a.cruise_type = #{cruiseType, jdbcType=INTEGER}
 and a.cruise_id = #{cruiseId, jdbcType=BIGINT}
 and a.cruise_name like concat('%',#{cruiseName, jdbcType=VARCHAR},'%') 
 and a.cruise_content = #{cruiseContent, jdbcType=VARCHAR}
 and a.position_type = #{positionType, jdbcType=VARCHAR}
 and a.unit = #{unit, jdbcType=VARCHAR}
 and a.if_sy = #{ifSy, jdbcType=INTEGER}
 and a.sy_type = #{syType, jdbcType=INTEGER}
 and a.if_videotape = #{ifVideotape, jdbcType=INTEGER}
 and a.videotape_time = #{videotapeTime, jdbcType=VARCHAR}
 and a.text_desc = #{textDesc, jdbcType=VARCHAR}
 and a.sort = #{sort, jdbcType=VARCHAR}

select a.device_mete_id
from  t_std_devicemete a
where 1=1
and a.mete_name like concat('%',#{meteName, jdbcType=VARCHAR},'%') 
 and a.device_id = #{deviceId, jdbcType=BIGINT}
 and a.custom_id = #{customId, jdbcType=VARCHAR}

SELECT a.*, b.cruise_type as cruiseType, b.cruise_id as cruiseId, c.dict_note as cruiseTypeName, d.device_name as deviceName, e.dict_note as customName FROM t_std_devicemete a LEFT JOIN t_cruise_point_instance b ON a.device_mete_id = b.device_mete_id LEFT JOIN t_dict_business c ON b.cruise_type = c.dict_code left join t_std_device d on a.device_id = d.device_id and a.custom_id = d.custom_id left join t_dict_business e on a.custom_id = e.dict_code where 1=1 and a.device_mete_id in
#{deviceMeteId,jdbcType=BIGINT}
order by a.device_id,a.custom_id,device_mete_id desc

SELECT a.*, b.cruise_type as cruiseType, b.cruise_id as cruiseId, c.dict_note as cruiseTypeName, d.device_id as deviceId, d.device_name as deviceName, e.dict_note as meteKindName, j.mete_id as deviceMeteId FROM t_cfg_mete a LEFT JOIN t_cruise_point_instance b ON a.mete_id = b.device_mete_id left join t_dict_business e on e.dict_code = a.mete_kind LEFT JOIN t_dict_business c ON b.cruise_type = c.dict_code left join (select device_id,mete_id from t_cfg_teleadjust f union all (select device_id,mete_id from t_cfg_telecontrol g ) union all (select device_id,mete_id from t_cfg_telemeter h ) union all (select device_id,mete_id from t_cfg_telesignal i)) j on a.mete_id = j.mete_id left join t_cfg_device d on j.device_id = d.device_id where a.mete_id in
#{meteId,jdbcType=VARCHAR}
order by a.mete_id

